const n=[{id:"1",slug:"how-to-distribute-your-music-independently",featured:!0,coverGradient:"from-blue-600 to-cyan-500",title:"How to Distribute Your Music Independently in 2026",readTime:"8 min read",category:"Distribution",date:"March 10, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Independent distribution has never been more powerful. Learn how to get your music on every major platform, keep 100% of your rights, and maximize your royalty earnings from day one.",sections:[{type:"paragraph",content:"The music industry has fundamentally shifted. Independent artists now have access to the same distribution infrastructure that major labels use — and in many cases, they can reach listeners faster and keep far more of their revenue."},{type:"heading",content:"Why Independent Distribution Makes Sense"},{type:"paragraph",content:"When you distribute through a major label deal, you typically sign away between 50–80% of your masters and recording royalties. With modern independent distribution platforms, you keep 100% of your ownership and typically 80–100% of your net revenue."},{type:"list",content:"The core advantages of going independent:",items:["Full ownership of your masters and publishing rights","Faster release timelines — no committee approvals","Direct access to platform analytics and fan data","Flexible pricing and promotional control","Ability to pivot your strategy based on real-time data"]},{type:"heading",content:"Getting on Every Major Platform"},{type:"paragraph",content:"Your music needs to be on Spotify, Apple Music, Amazon Music, YouTube Music, Tidal, Deezer, and dozens of smaller platforms. Doing this manually would take weeks. A distribution service handles all of this in a single upload."},{type:"tip",content:"Always deliver your audio at 24-bit / 44.1kHz WAV. Platforms will encode down to streaming quality, but starting with the best source preserves maximum fidelity."},{type:"heading",content:"Metadata Is Everything"},{type:"paragraph",content:"Poor metadata is the silent killer of streaming revenue. Missing ISRC codes, incorrect songwriter credits, or wrong genre tags can prevent your music from being surfaced in algorithmic playlists and editorial consideration."},{type:"numbered",content:"Metadata checklist before every release:",items:["ISRC code for every track (auto-generated by most distributors)","Correct songwriter and producer splits entered in your publishing admin","UPC/EAN barcode for the release","Accurate genre and sub-genre tags","Release date set at least 7 days in advance for editorial pitch eligibility","Cover art at 3000x3000px minimum, no explicit content indicators if clean"]},{type:"quote",content:"Your metadata is your music's passport. Without it being correct, your music can't travel to where your fans are."},{type:"heading",content:"Maximizing Royalty Collection"},{type:"paragraph",content:"Distribution royalties are only one stream of income. You're also entitled to performance royalties (collected by PROs like ASCAP, BMI, or SESAC), mechanical royalties, and sync licensing fees. Many independent artists leave significant money on the table by not registering for all of these."},{type:"callout",content:"Make sure you're registered with a Performing Rights Organization before your first release. It can take 3–6 months to start seeing royalty statements, and they won't backfill indefinitely."}]},{id:"2",slug:"understanding-music-royalties",featured:!1,coverGradient:"from-purple-600 to-pink-500",title:"Understanding Music Royalties: A Complete Guide for Artists",readTime:"10 min read",category:"Royalties",date:"March 5, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Royalties are complex — but understanding them is one of the highest-leverage things you can do for your music career. This guide breaks down every royalty type, who collects them, and how to make sure you're getting paid.",sections:[{type:"paragraph",content:"There are more types of music royalties than most artists realize. Missing even one category can mean thousands of dollars in uncollected earnings per year. Let's break them all down."},{type:"heading",content:"Master Recording Royalties"},{type:"paragraph",content:"These are paid to the owner of the master recording — the actual sound file. If you recorded and paid for your own music, you own the master. If a label funded the recording, they likely own it."},{type:"heading",content:"Publishing / Mechanical Royalties"},{type:"paragraph",content:"Mechanical royalties are paid for the reproduction of a composition — every stream, download, or physical copy triggers a mechanical royalty. These flow to the songwriter and publisher, not the recording owner."},{type:"tip",content:"Even if you write and record all your own music, you need both a master rights deal AND a publishing deal (or publishing admin) to collect all the money you're owed."},{type:"heading",content:"Performance Royalties"},{type:"paragraph",content:"Every time your song is played on radio, TV, in a venue, or streamed (in some territories), a performance royalty is generated. These are collected by your PRO (ASCAP, BMI, SESAC in the US) and paid to songwriters and publishers."},{type:"heading",content:"Sync Licensing Fees"},{type:"paragraph",content:"When your music is used in a film, TV show, commercial, or video game, you earn a sync fee. These are negotiated directly and can range from a few hundred dollars to six figures for a major placement."},{type:"callout",content:"Sync licensing is one of the fastest-growing income streams for independent artists. A single TV placement can outperform years of streaming revenue."}]},{id:"3",slug:"grow-your-fanbase-with-social-media",featured:!1,coverGradient:"from-orange-500 to-red-500",title:"How to Grow a Genuine Fanbase with Social Media in 2026",readTime:"7 min read",category:"Marketing",date:"February 28, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Follower counts don't pay bills — engaged fans do. This guide covers the social media strategies that actually move the needle for independent artists, from short-form video to community building.",sections:[{type:"paragraph",content:"The artists who win on social media in 2026 aren't the ones posting the most — they're the ones building the deepest connections. Here's what that looks like in practice."},{type:"heading",content:"Short-Form Video Is Non-Negotiable"},{type:"paragraph",content:"TikTok, Instagram Reels, and YouTube Shorts are the most efficient discovery mechanisms for music right now. You don't need a production team — a phone and a genuine moment is enough."},{type:"tip",content:"Post the first 15 seconds of your most emotionally impactful moment. Don't start at the beginning of the song — start at the hook that makes people feel something."},{type:"heading",content:"Consistency Over Virality"},{type:"paragraph",content:"One viral video won't build a career. Three posts a week for two years will. The algorithm rewards consistency, and your audience learns to expect and anticipate your content when you show up reliably."},{type:"heading",content:"Build Community, Not an Audience"},{type:"paragraph",content:"An audience watches. A community participates. Reply to every comment in your first hour of posting. Ask questions. Share your process, your failures, your inspirations. Let people in."},{type:"quote",content:"The artists who last aren't the ones who got the most streams on one song. They're the ones whose fans would follow them anywhere."}]},{id:"4",slug:"playlist-pitching-strategy",featured:!1,coverGradient:"from-green-500 to-teal-500",title:"The Complete Spotify Playlist Pitching Strategy for Independent Artists",readTime:"9 min read",category:"Distribution",date:"February 20, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Playlist placement can 10x your monthly listeners overnight. Learn how to craft the perfect editorial pitch, identify the right independent curators, and time your submissions for maximum impact.",sections:[{type:"paragraph",content:"Playlist placement is still one of the most powerful growth levers available to independent artists. But the pitch process is misunderstood — most artists focus on the wrong things."},{type:"heading",content:"Spotify for Artists Editorial Pitch"},{type:"paragraph",content:"You can submit one unreleased song for editorial consideration through Spotify for Artists up to 7 days before release. This is your shot at Discover Weekly, Release Radar, and genre playlists."},{type:"numbered",content:"How to write a pitch that gets read:",items:["Write 2–3 sentences about what makes this song unique — mood, story, production style","Name specific playlists you're targeting and explain why the song fits","Include any notable press, sync placements, or social moments","Be specific about genre and sub-genre — editors curate narrow niches","Mention if there's a tie-in event (tour, album release, cultural moment)"]},{type:"tip",content:"Submit your pitch the moment you have a finalized track ready — don't wait until the last day. Earlier submissions get more time in the review queue."},{type:"heading",content:"Independent Curator Outreach"},{type:"paragraph",content:"Don't overlook independent playlist curators. A playlist with 50,000 followers of highly engaged listeners in your niche can outperform a 500,000-follower algorithmic playlist with passive listeners."},{type:"callout",content:"Never pay for playlist placements. It violates Spotify's terms of service and can result in your music being removed. Legitimate curators don't charge artists."}]},{id:"5",slug:"recording-budget-guide",featured:!1,coverGradient:"from-indigo-600 to-purple-600",title:"How to Record a Professional Album on Any Budget",readTime:"11 min read",category:"Production",date:"February 14, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Budget doesn't determine quality — decisions do. Learn how independent artists at every budget level can achieve professional-sounding releases, from bedroom studios to full recording sessions.",sections:[{type:"paragraph",content:"The gap between a $500 home recording and a $50,000 studio album is closing every year. Plugins, room treatment, and engineering knowledge now matter more than gear budgets."},{type:"heading",content:"Budget Tier 1: Under $1,000"},{type:"list",items:["Audio interface: Focusrite Scarlett Solo or 2i2 ($100–200)","Condenser microphone: Audio-Technica AT2020 ($100)","DAW: GarageBand (free) or Reaper ($60)","Acoustic treatment: DIY panels or moving blankets ($50–200)","Headphones: Sony MDR-7506 ($100)"]},{type:"heading",content:"Budget Tier 2: $1,000–$5,000"},{type:"paragraph",content:"At this level, you can invest in better monitoring (studio monitors over headphones make a massive difference), a higher-quality microphone, and potentially hire a mixing engineer for your final mixes."},{type:"tip",content:"Spending $200–500 on professional mixing and mastering for a track you plan to release is almost always worth it. Your performance and production can be great — a fresh set of trained ears catches what you miss."},{type:"heading",content:"The One Investment That Always Pays Off"},{type:"quote",content:"Acoustic treatment is the single best investment you can make in your home studio. Even the best microphone sounds mediocre in an untreated room."}]},{id:"6",slug:"music-licensing-basics",featured:!1,coverGradient:"from-yellow-500 to-orange-500",title:"Music Licensing Basics: How to License Your Music for Film & TV",readTime:"8 min read",category:"Licensing",date:"February 7, 2026",author:"B-Lawz Music",authorRole:"Founder, Max Booster",excerpt:"Sync licensing is one of the most lucrative and underutilized income streams for independent artists. Here's a practical introduction to getting your music placed in film, TV, and advertising.",sections:[{type:"paragraph",content:"Sync licensing — placing your music in visual media — can generate significant income while dramatically expanding your audience. But it requires specific preparation that most artists skip."},{type:"heading",content:"Clearing Your Music for Sync"},{type:"paragraph",content:"Before any music supervisor can use your track, you need to be able to confirm that you control or can license both the master recording AND the publishing rights. If you co-wrote a song, all co-writers must be cleared."},{type:"callout",content:"Sample clearance is the most common deal-breaker. If your track contains an uncleared sample, no legitimate sync opportunity can move forward."},{type:"heading",content:"What Music Supervisors Want"},{type:"list",content:"When pitching to music supervisors:",items:["Instrumentals and stems — they often need to adjust levels for dialogue","Clean and explicit versions of every vocal track","Tracks organized by mood, tempo, and genre","Fast turnaround — deadlines in sync are brutal","Reasonable, pre-discussed licensing rates"]},{type:"tip",content:'Build a library of 30–60 second "trailer edits" of your best tracks. This is one of the most requested formats for ad agencies and trailer houses.'}]}];function s(e){return n.find(o=>o.slug===e)}function c(e,o=3){const a=s(e);if(!a)return n.slice(0,o);const r=n.filter(t=>t.slug!==e&&t.category===a.category),i=n.filter(t=>t.slug!==e&&t.category!==a.category);return[...r,...i].slice(0,o)}export{c as a,n as b,s as g};
